#include "engine/sblr/sblr_versioned_branch_create_runtime.hpp"
#include "core/hash/hash_digest.hpp"
#include <algorithm>
#include <cstring>
namespace scratchbird::engine::sblr{namespace{template<class A>bool nz(const A&a){return std::any_of(a.begin(),a.end(),[](auto v){return v!=0;});}void put(std::vector<std::uint8_t>&o,std::uint64_t v,std::size_t n){for(std::size_t i=0;i<n;++i)o.push_back((std::uint8_t)(v>>(8*i)));}std::uint64_t get(const std::uint8_t*p,std::size_t n){std::uint64_t v=0;for(std::size_t i=0;i<n;++i)v|=(std::uint64_t)p[i]<<(8*i);return v;}std::array<std::uint8_t,32>hs(const char*d,const std::uint8_t*p){std::vector<std::uint8_t>x(d,d+std::strlen(d));x.insert(x.end(),p,p+352);return core::hash::ComputeSha256Digest(x).digest;}std::vector<std::uint8_t>enc(const char*m,const std::array<std::uint8_t,376>&b,const char*d){std::vector<std::uint8_t>o={(std::uint8_t)m[0],(std::uint8_t)m[1],(std::uint8_t)m[2],(std::uint8_t)m[3],1,0,0,0};o.insert(o.end(),b.begin(),b.end());std::fill(o.begin()+352,o.begin()+384,0);auto h=hs(d,o.data());std::copy(h.begin(),h.end(),o.begin()+352);return o;}bool dec(const std::uint8_t*p,std::size_t n,const char*m,std::array<std::uint8_t,376>*b,const char*d,std::string*e){if(!p||!b||n!=384||std::memcmp(p,m,4)||p[4]!=1||p[5]||p[6]||p[7]){if(e)*e="frame invalid";return false;}auto h=hs(d,p);if(!std::equal(h.begin(),h.end(),p+352)){if(e)*e="hash invalid";return false;}std::copy_n(p+8,376,b->begin());return true;}}
std::vector<std::uint8_t>EncodeSblrVersionedBranchCreateRequestV1(const SblrVersionedBranchCreateRequestV1&v){if(!nz(v.operation)||!nz(v.receipt)||v.descriptor_length!=384)return{};std::vector<std::uint8_t>o={'S','B','D','Q'};put(o,1,2);put(o,8,2);put(o,7621,4);put(o,608,4);o.insert(o.end(),v.operation.begin(),v.operation.end());o.insert(o.end(),v.receipt.begin(),v.receipt.end());put(o,384,4);o.insert(o.end(),12,0);return o;}bool DecodeSblrVersionedBranchCreateRequestV1(const std::uint8_t*p,std::size_t n,SblrVersionedBranchCreateRequestV1*o,std::string*e){if(!o||!p||n!=64||std::memcmp(p,"SBDQ",4)||get(p+4,2)!=1||get(p+6,2)!=8||get(p+8,4)!=7621||get(p+12,4)!=608||std::any_of(p+52,p+64,[](auto v){return v!=0;})){if(e)*e="request invalid";return false;}std::copy_n(p+16,16,o->operation.begin());std::copy_n(p+32,16,o->receipt.begin());o->descriptor_length=(std::uint32_t)get(p+48,4);return nz(o->operation)&&nz(o->receipt)&&o->descriptor_length==384;}std::vector<std::uint8_t>EncodeSblrVersionedBranchCreateDescriptorV1(const SblrVersionedBranchCreateDescriptorV1&v){return nz(v.body)?enc("SBDD",v.body,"SBOD|SBDD|v1"):std::vector<std::uint8_t>{};}bool DecodeSblrVersionedBranchCreateDescriptorV1(const std::uint8_t*p,std::size_t n,SblrVersionedBranchCreateDescriptorV1*o,std::string*e){return o&&dec(p,n,"SBDD",&o->body,"SBOD|SBDD|v1",e);}std::vector<std::uint8_t>EncodeSblrVersionedBranchCreateResultV1(const SblrVersionedBranchCreateResultV1&v){return nz(v.body)?enc("SLRR",v.body,"ScratchBird.SblrVersionedBranchCreate.Result.V1"):std::vector<std::uint8_t>{};}bool DecodeSblrVersionedBranchCreateResultV1(const std::uint8_t*p,std::size_t n,SblrVersionedBranchCreateResultV1*o,std::string*e){return o&&dec(p,n,"SLRR",&o->body,"ScratchBird.SblrVersionedBranchCreate.Result.V1",e);}}
